input.command:
psql -d r3_test -c "DO \$\$
DECLARE
    e_no_data constant text := 'no_data_found';
BEGIN
    RAISE EXCEPTION 'probe: raising named condition' USING ERRCODE = e_no_data;
EXCEPTION
    WHEN no_data_found THEN
        RAISE NOTICE 'caught by the no_data_found arm';
    WHEN OTHERS THEN
        RAISE NOTICE 'WRONG arm: caught by OTHERS';
END;
\$\$;"

